      environmentSummary: {
        exampleKeysCount: 18,
        missingProdKeys: ['DB_PASSWORD', 'JWT_SECRET', 'STRIPE_WEBHOOK_KEY', 'API_SALT'],
        extraProdKeys: []
      }
