// --- AI COPILOT CHAT (Real Local Inference & Code Markdown Rendering) ---
function setupAiChatStudio(api: any): void {
  const btnSend = document.getElementById('btnChatSend');
  const txtInput = document.getElementById('txtChatInput') as HTMLInputElement;
  const messagesStream = document.getElementById('chatMessagesStream');
  const btnClear = document.getElementById('btnChatClear');

  btnClear?.addEventListener('click', () => {
    chatHistory = [];
    if (messagesStream) {
      messagesStream.innerHTML = `<div class="chat-bubble ai" style="background: var(--card-bg); padding: 12px 14px; border-radius: 8px; border: 1px solid var(--border); max-width: 90%;">
        <div style="font-weight: 700; color: var(--accent); margin-bottom: 4px; display: flex; align-items: center; gap: 6px;">
          <span>🚀</span> Evolve AI Copilot:
        </div>
        <div style="color: #e2e8f0; font-size: 12px; line-height: 1.5;">
          Hello! I am your air-gapped Enterprise Delivery AI Copilot. Ask me about schema migrations, dbt marts, client APIs, or code modernizations.
        </div>
      </div>`;
    }
    showToast('✓ Chat history cleared.');
  });

  const sendMessage = async () => {
    const text = txtInput?.value.trim();
    if (!text || !messagesStream) return;

    // 1. Append User Bubble
    const userDiv = document.createElement('div');
    userDiv.className = 'chat-bubble user';
    userDiv.style.cssText = 'background: #1e3a29; padding: 10px 14px; border-radius: 8px; border: 1px solid #89d185; align-self: flex-end; max-width: 80%;';
    userDiv.innerHTML = `<div style="font-weight: 700; font-size: 11px; color: #89d185; margin-bottom: 3px;">You:</div><div style="color: #fff; font-size: 12px; white-space: pre-wrap;">${escapeHtml(text)}</div>`;
    messagesStream.appendChild(userDiv);

    txtInput.value = '';
    messagesStream.scrollTop = messagesStream.scrollHeight;

    // 2. Append Thinking Indicator Bubble
    const aiDiv = document.createElement('div');
    aiDiv.className = 'chat-bubble ai';
    aiDiv.style.cssText = 'background: var(--card-bg); padding: 12px 14px; border-radius: 8px; border: 1px solid var(--border); max-width: 90%;';
    aiDiv.innerHTML = `<div style="font-weight: 700; color: var(--accent); margin-bottom: 4px; display: flex; align-items: center; gap: 6px;">
      <span>🚀</span> Evolve AI:
    </div>
    <div class="ai-content-body" style="color: var(--text-secondary); font-size: 12px; font-style: italic;">
      Thinking & generating solution... ⏳
    </div>`;
    messagesStream.appendChild(aiDiv);
    messagesStream.scrollTop = messagesStream.scrollHeight;

    // 3. Query Real AI Backend
    try {
      if (api?.ai) {
        const response = await api.ai.chat({
          prompt: text,
          history: chatHistory,
          model: activeSelectedModel
        });

        const content = response.content || 'I processed your request.';
        const contentBody = aiDiv.querySelector('.ai-content-body');
        if (contentBody) {
          contentBody.removeAttribute('style');
          (contentBody as HTMLElement).style.cssText = 'color: #e2e8f0; font-size: 12px; line-height: 1.5;';
          contentBody.innerHTML = formatMarkdownToHtml(content);
        }

        chatHistory.push({ role: 'user', content: text });
        chatHistory.push({ role: 'assistant', content: content });
      } else {
        const contentBody = aiDiv.querySelector('.ai-content-body');
        if (contentBody) {
          contentBody.innerHTML = formatMarkdownToHtml('```python\n# Solution\nprint("Hello World!")\n```');
        }
      }
    } catch (err: any) {
      const contentBody = aiDiv.querySelector('.ai-content-body');
      if (contentBody) {
        contentBody.innerHTML = `<span style="color: var(--error);">Error generating AI response: ${err.message}</span>`;
      }
    }

    messagesStream.scrollTop = messagesStream.scrollHeight;
  };

  btnSend?.addEventListener('click', sendMessage);
  txtInput?.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  });
}

function escapeHtml(str: string): string {
  return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function formatInlineMarkdown(text: string): string {
  let s = text;
  // Inline code: `code`
  s = s.replace(/`([^`]+)`/g, '<code style="background: rgba(255,255,255,0.08); padding: 1px 5px; border-radius: 3px; font-family: monospace; color: #4ec9b0; font-size: 10.5px;">$1</code>');
  // Bold: **text**
  s = s.replace(/\*\*(.*?)\*\*/g, '<strong style="color: #fff;">$1</strong>');
  // Italics: *text*
  s = s.replace(/\*(.*?)\*/g, '<em style="color: #9cdcfe;">$1</em>');
  return s;
}

function formatMarkdownToHtml(markdown: string): string {
  if (!markdown) return '';
  const codeBlocks: string[] = [];
  let text = markdown.replace(/```([a-zA-Z0-9_-]*)\n?([\s\S]*?)```/g, (_match, _lang, code) => {
    const idx = codeBlocks.length;
    codeBlocks.push(`<pre style="background: #111; padding: 12px; border-radius: 6px; border: 1px solid rgba(255,255,255,0.1); overflow-x: auto; margin: 10px 0;"><code style="font-family: Consolas, monospace; font-size: 11.5px; color: #9cdcfe;">${escapeHtml(code.trim())}</code></pre>`);
    return `%%%CODEBLOCK_${idx}%%%`;
  });

  const lines = text.split('\n');
  const processedLines: string[] = [];
  let inTable = false;
  let tableHeader: string[] = [];
  let tableRows: string[][] = [];

  const flushTable = () => {
    if (!inTable) return;
    let tableHtml = '<div style="overflow-x: auto; margin: 12px 0;"><table style="width: 100%; border-collapse: collapse; font-size: 11px; background: rgba(0,0,0,0.25); border: 1px solid var(--border); border-radius: 6px; overflow: hidden;">';
    if (tableHeader.length > 0) {
      tableHtml += '<thead><tr style="background: rgba(78, 201, 176, 0.12); border-bottom: 2px solid var(--border);">';
      tableHeader.forEach(th => {
        tableHtml += `<th style="padding: 8px 12px; text-align: left; color: var(--accent); font-weight: 700; border-right: 1px solid rgba(255,255,255,0.06);">${formatInlineMarkdown(th.trim())}</th>`;
      });
      tableHtml += '</tr></thead>';
    }
    tableHtml += '<tbody>';
    tableRows.forEach(row => {
      tableHtml += '<tr style="border-bottom: 1px solid rgba(255,255,255,0.06);">';
      row.forEach(cell => {
        tableHtml += `<td style="padding: 7px 12px; color: #cbd5e1; border-right: 1px solid rgba(255,255,255,0.04);">${formatInlineMarkdown(cell.trim())}</td>`;
      });
      tableHtml += '</tr>';
    });
    tableHtml += '</tbody></table></div>';
    processedLines.push(tableHtml);
    inTable = false;
    tableHeader = [];
    tableRows = [];
  };

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line.startsWith('|') && line.endsWith('|')) {
      const cells = line.split('|').slice(1, -1);
      const isSeparator = cells.every(c => /^[\s:-]+$/.test(c));
      if (isSeparator) continue;
      if (!inTable) {
        inTable = true;
        tableHeader = cells;
      } else {
        tableRows.push(cells);
      }
    } else {
      if (inTable) flushTable();
      processedLines.push(lines[i]);
    }
  }
  if (inTable) flushTable();

  let inUl = false;
  let inOl = false;
  const resultLines: string[] = [];

  const closeLists = () => {
    if (inUl) { resultLines.push('</ul>'); inUl = false; }
    if (inOl) { resultLines.push('</ol>'); inOl = false; }
  };

  for (let i = 0; i < processedLines.length; i++) {
    const line = processedLines[i];
    const trimmed = line.trim();

    if (trimmed.startsWith('%%%CODEBLOCK_') || trimmed.startsWith('<div style="overflow-x:')) {
      closeLists();
      resultLines.push(line);
      continue;
    }

    if (/^---{3,}$/.test(trimmed)) {
      closeLists();
      resultLines.push('<hr style="border: none; border-top: 1px solid var(--border); margin: 14px 0;">');
      continue;
    }

    if (/^#\s+(.+)$/.test(trimmed)) {
      closeLists();
      resultLines.push(`<h2 style="font-size: 15px; font-weight: 700; color: #fff; margin: 14px 0 8px 0; border-bottom: 1px solid var(--border); padding-bottom: 5px;">${formatInlineMarkdown(trimmed.replace(/^#\s+/, ''))}</h2>`);
      continue;
    }
    if (/^##\s+(.+)$/.test(trimmed)) {
      closeLists();
      resultLines.push(`<h3 style="font-size: 13.5px; font-weight: 700; color: var(--accent); margin: 12px 0 6px 0;">${formatInlineMarkdown(trimmed.replace(/^##\s+/, ''))}</h3>`);
      continue;
    }
    if (/^###\s+(.+)$/.test(trimmed)) {
      closeLists();
      resultLines.push(`<h4 style="font-size: 12.5px; font-weight: 700; color: #38bdf8; margin: 10px 0 6px 0; display: flex; align-items: center; gap: 6px;">${formatInlineMarkdown(trimmed.replace(/^###\s+/, ''))}</h4>`);
      continue;
    }
    if (/^####\s+(.+)$/.test(trimmed)) {
      closeLists();
      resultLines.push(`<h5 style="font-size: 11.5px; font-weight: 700; color: #fbbf24; margin: 8px 0 4px 0;">${formatInlineMarkdown(trimmed.replace(/^####\s+/, ''))}</h5>`);
      continue;
    }

    if (/^>\s*(.+)$/.test(trimmed)) {
      closeLists();
      resultLines.push(`<blockquote style="border-left: 3px solid var(--accent); background: rgba(78, 201, 176, 0.08); padding: 8px 12px; margin: 8px 0; border-radius: 0 4px 4px 0; color: #cbd5e1; font-size: 11px;">${formatInlineMarkdown(trimmed.replace(/^>\s*/, ''))}</blockquote>`);
      continue;
    }

    if (/^[-*]\s+(.+)$/.test(trimmed)) {
      if (inOl) { resultLines.push('</ol>'); inOl = false; }
      if (!inUl) { resultLines.push('<ul style="margin: 6px 0 8px 0; padding-left: 20px; line-height: 1.6;">'); inUl = true; }
      resultLines.push(`<li style="margin-bottom: 3px; color: #cbd5e1;">${formatInlineMarkdown(trimmed.replace(/^[-*]\s+/, ''))}</li>`);
      continue;
    }

    if (/^\d+\.\s+(.+)$/.test(trimmed)) {
      if (inUl) { resultLines.push('</ul>'); inUl = false; }
      if (!inOl) { resultLines.push('<ol style="margin: 6px 0 8px 0; padding-left: 20px; line-height: 1.6;">'); inOl = true; }
      resultLines.push(`<li style="margin-bottom: 3px; color: #cbd5e1;">${formatInlineMarkdown(trimmed.replace(/^\d+\.\s+/, ''))}</li>`);
      continue;
    }

    closeLists();
    if (trimmed === '') {
      resultLines.push('<div style="height: 6px;"></div>');
    } else {
      resultLines.push(`<p style="margin: 0 0 6px 0; line-height: 1.5; color: #cbd5e1;">${formatInlineMarkdown(trimmed)}</p>`);
    }
  }
  closeLists();

  let finalHtml = resultLines.join('\n');
  finalHtml = finalHtml.replace(/%%%CODEBLOCK_(\d+)%%%/g, (_m, idx) => codeBlocks[parseInt(idx, 10)] || '');
  return finalHtml;
}

